css:
.header, .footer {
      text-align: center;
      margin-bottom: 20px;
    }
    .header h1 {
      margin-bottom:35px;
      font-size: 18px;
      text-transform: uppercase;
    }
    .header .info {
      width:100%;
      display: flex;
      margin-top: 10px;
    }

   .info>div{
       flex:1;
        text-align: left;
    }

    .info>.address{
       flex:2;
        text-align: left;
    }



    .header>.info>div>div{
        margin-bottom:10px;
    }

    .header .info
    .section {
      margin-bottom: 20px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 10px;
      color:black;
    }
    table th, table td {
      border: 1px solid black;
      padding: 8px;
      text-align: left;
      font-size: 14px;
    }
    table th {
      background-color: #ccc;
    }

    .field-info{
        display:flex;
    }

    .address{
        padding-right:70px;
        margin-bottom: 30px;
    }

    .address>p{
        padding:6px;
    }
    .address>p:first-child{
        background-color:#ccc;
        padding:6px;
    }

    .top-table td{
        width:20%;
        height:30px;
    }

    .footer{
        flex:1;
        display:flex;
        margin-top:30px;
    }

    .footer>div:last-child{
        flex:3;
        border-bottom: 1px solid #000;
        height:80px;
        margin-right:60px;
        margin-left: 30px;
    }

    .footer>div:first-child{
        flex:5;
        border:2px solid black;
        margin-bottom:auto;
    }

    .blank-column{
        border-width:0px;
    }
